class InputReader:
    def __init__(self, input_stream):
        self.tokens = []
        self.input_stream = input_stream

    def next(self):
        while not self.tokens:
            line = self.input_stream.readline()
            if not line:
                return ''
            self.tokens = line.strip().split()
        return self.tokens.pop(0)

    def nextInt(self):
